class CavaContractStatus(str, Enum):
    BORRADOR = "BORRADOR"
    CELEBRADO = "CELEBRADO"
    VIGENTE = "VIGENTE"
    PROXIMA_RENOVACION = "PROXIMA_RENOVACION"
    RENOVACION_PENDIENTE = "RENOVACION_PENDIENTE"
    GRACIA = "GRACIA"
    VENCIDO = "VENCIDO"
    BLOQUEADO = "BLOQUEADO"
    CANCELADO = "CANCELADO"


class CavaPaymentStatus(str, Enum):
    SIN_PAGO = "SIN_PAGO"
    PARCIAL = "PARCIAL"
    CUBIERTO = "CUBIERTO"
    SOBRE_PAGO = "SOBRE_PAGO"


class CavaBenefitStatus(str, Enum):
    PENDIENTE = "PENDIENTE"
    RESTRINGIDO = "RESTRINGIDO"
    ACTIVO = "ACTIVO"
    BLOQUEADO = "BLOQUEADO"


@dataclass(frozen=True)
class CavaContractFinancialState:
    contract_id: str
    contract_status: CavaContractStatus
    amount_due: float
    amount_paid: float
    dossier_complete: bool
    contract_accepted: bool


@dataclass(frozen=True)
class CavaActivationPolicy:
    minimum_paid_ratio: float
    require_contract_accepted: bool = True
    require_dossier_complete: bool = True


@dataclass(frozen=True)
class CavaActivationException:
    authorization_reference: str
    authorized_by_user_id: str
    reason: str


def paid_ratio(state: CavaContractFinancialState) -> float:
    due = float(state.amount_due)
    paid = float(state.amount_paid)
    if due < 0 or paid < 0:
        raise ValueError("Los importes no pueden ser negativos")
    if due == 0:
        return 1.0 if paid >= 0 else 0.0
    return paid / due


def payment_status(state: CavaContractFinancialState) -> CavaPaymentStatus:
    ratio = paid_ratio(state)
    if state.amount_paid == 0:
        return CavaPaymentStatus.SIN_PAGO
    if ratio < 1:
        return CavaPaymentStatus.PARCIAL
    if ratio == 1:
        return CavaPaymentStatus.CUBIERTO
    return CavaPaymentStatus.SOBRE_PAGO


def validate_activation_policy(policy: CavaActivationPolicy) -> None:
    threshold = float(policy.minimum_paid_ratio)
    if threshold < 0 or threshold > 1:
        raise ValueError("minimum_paid_ratio debe estar entre 0 y 1")


def validate_activation_exception(exception: CavaActivationException) -> None:
    for field_name, value in (("authorization_reference", exception.authorization_reference), ("authorized_by_user_id", exception.authorized_by_user_id), ("reason", exception.reason)):
        if not str(value or "").strip():
            raise ValueError(f"CavaActivationException requiere {field_name}")


def resolve_benefit_status(state: CavaContractFinancialState, policy: CavaActivationPolicy, exception: Optional[CavaActivationException] = None) -> CavaBenefitStatus:
    validate_activation_policy(policy)
    if state.contract_status in {CavaContractStatus.BLOQUEADO, CavaContractStatus.CANCELADO, CavaContractStatus.VENCIDO}:
        return CavaBenefitStatus.BLOQUEADO

    contract_ok = (not policy.require_contract_accepted) or state.contract_accepted
    dossier_ok = (not policy.require_dossier_complete) or state.dossier_complete
    payment_ok = paid_ratio(state) >= policy.minimum_paid_ratio

    if contract_ok and dossier_ok and payment_ok:
        return CavaBenefitStatus.ACTIVO

    if exception is not None:
        validate_activation_exception(exception)
        if state.contract_status in {CavaContractStatus.CELEBRADO, CavaContractStatus.VIGENTE, CavaContractStatus.GRACIA}:
            return CavaBenefitStatus.RESTRINGIDO

    return CavaBenefitStatus.PENDIENTE
